function slugify(title) {
  return title
    .trim()
    .toLowerCase()
    .replace(/\s+/g, '-')
    .replace(/[^a-z0-9-]/g, '');
}

const slug = slugify('  JavaScript Reflex Trainer App  ');

console.log(slug);

